import { useMemo,useState } from 'react';import { Link,useParams } from 'react-router-dom';import { mockProducts,formatMoney } from '../../lib/api';import { useApp } from '../../contexts/AppContext';
export default function Produto(){const {slug}=useParams();const p=mockProducts.find(x=>x.slug===slug)||mockProducts[0];const [qtd,setQtd]=useState(1);const specs=useMemo(()=>Object.fromEntries(Object.entries(p.especificacoes||{}).map(([k,v])=>[k,v[0]])),[p]);const [sel,setSel]=useState<Record<string,string>>(specs);const {addToCart}=useApp();return <section className="containerx py-12 fade"><div className="grid lg:grid-cols-2 gap-10"><div><img src={p.imagem_principal} className="rounded-3xl w-full h-[520px] object-cover shadow-premium"/><div className="grid grid-cols-4 gap-3 mt-3">{[p.imagem_principal,...(p.imagens_adicionais||[])].slice(0,4).map(i=><img key={i} src={i} className="rounded-2xl h-24 w-full object-cover"/>)}</div></div><div><p className="badge bg-accent/10 text-accent inline-block">{p.categoria_nome}</p><h1 className="font-display text-5xl text-primary mt-4">{p.nome}</h1><p className="text-gray-600 text-lg mt-4">{p.descricao}</p><div className="mt-6"><b className="text-4xl text-primary">{formatMoney(p.preco)}</b>{p.preco_original&&<span className="line-through text-gray-400 ml-3">{formatMoney(p.preco_original)}</span>}</div><p className="mt-4 text-sm text-gray-600">Estoque: {p.estoque} unidades · Produção: {p.tempo_producao} dias</p><div className="mt-6 grid gap-4">{Object.entries(p.especificacoes||{}).map(([k,arr])=><label key={k} className="font-bold">{k}<select className="input mt-2" value={sel[k]} onChange={e=>setSel({...sel,[k]:e.target.value})}>{arr.map(v=><option key={v}>{v}</option>)}</select></label>)}</div><div className="flex gap-3 mt-6"><input className="input w-28" type="number" min={1} value={qtd} onChange={e=>setQtd(Number(e.target.value))}/><button className="btn btn-primary" onClick={()=>addToCart(p,qtd,sel)}>Adicionar ao Carrinho</button><Link className="btn btn-dark" to="/checkout" onClick={()=>addToCart(p,qtd,sel)}>Comprar Agora</Link></div><div className="card p-6 mt-8"><h3 className="font-display text-2xl">Descrição completa</h3><p className="text-gray-600 mt-3">{p.descricao_longa||'Produto personalizado com impressão de alta definição, revisão de acabamento e preparo profissional para entrega.'}</p></div></div></div><h2 className="font-display text-3xl mt-16 mb-6">Produtos Relacionados</h2><div className="grid md:grid-cols-3 gap-6">{mockProducts.filter(x=>x.id!==p.id).slice(0,3).map(r=><Link to={`/produto/${r.slug}`} className="card p-4" key={r.id}>{r.nome}<b className="block text-accent">{formatMoney(r.preco)}</b></Link>)}</div></section>}
